mapper.insert:
INSERT INTO quota_claim (claimNo, activityId, userId, grantAmount)
SELECT #{claimNo}, a.id, u.id, a.grantAmount
FROM quota_activity a JOIN `user` u ON u.id = #{userId}
WHERE a.id = #{activityId} AND a.status = 'published' AND a.grantAmount = #{grantAmount}
ON DUPLICATE KEY UPDATE claimNo = quota_claim.claimNo
